/* Deep Thought Education · Current Electricity — lessons and interactive labs.
   Generated by tools/build.py; loaded by assets/app.js the first time one of these lessons is opened. */
/* lab:current-electricity:start */
/** Shared canvas symbols for the circuit labs. */
var CE = {
  zig: function (ctx, x1, y1, x2, y2, color, w) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy), ux = dx / L, uy = dy / L, px = -uy, py = ux;
    var body = Math.min(46, L - 8), a = 7, cx = (x1 + x2) / 2, cy = (y1 + y2) / 2, s = body / 12, k, t, sg;
    ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = w || 2; ctx.lineJoin = 'round'; ctx.lineCap = 'round'; ctx.beginPath();
    ctx.moveTo(x1, y1); ctx.lineTo(cx - ux * body / 2, cy - uy * body / 2);
    for (k = 0; k < 6; k++) { t = -body / 2 + s * (2 * k + 1); sg = k % 2 ? 1 : -1; ctx.lineTo(cx + ux * t + px * a * sg, cy + uy * t + py * a * sg); }
    ctx.lineTo(cx + ux * body / 2, cy + uy * body / 2); ctx.lineTo(x2, y2); ctx.stroke(); ctx.restore();
  },
  /** Cell; the long (positive) plate faces point 2. */
  cell: function (ctx, x1, y1, x2, y2, color, bg) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy), ux = dx / L, uy = dy / L, px = -uy, py = ux, cx = (x1 + x2) / 2, cy = (y1 + y2) / 2, g = 4;
    ctx.save(); ctx.strokeStyle = color; ctx.lineCap = 'round';
    ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(cx - ux * g, cy - uy * g); ctx.moveTo(cx + ux * g, cy + uy * g); ctx.lineTo(x2, y2); ctx.stroke();
    ctx.lineWidth = 4.5; ctx.beginPath(); ctx.moveTo(cx - ux * g - px * 7, cy - uy * g - py * 7); ctx.lineTo(cx - ux * g + px * 7, cy - uy * g + py * 7); ctx.stroke();
    ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(cx + ux * g - px * 14, cy + uy * g - py * 14); ctx.lineTo(cx + ux * g + px * 14, cy + uy * g + py * 14); ctx.stroke();
    ctx.restore();
  },
  wire: function (ctx, pts, color, w) {
    ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = w || 2; ctx.lineJoin = 'round'; ctx.lineCap = 'round'; ctx.beginPath();
    pts.forEach(function (p, i) { i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]); }); ctx.stroke(); ctx.restore();
  },
  /** Dots marching along a polyline; `phase` in pixels. */
  flow: function (ctx, pts, phase, color, gap) {
    var segs = [], total = 0, i, d, s, L, p;
    for (i = 0; i < pts.length - 1; i++) { L = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]); segs.push(L); total += L; }
    gap = gap || 26; ctx.save(); ctx.fillStyle = color;
    for (d = ((phase % gap) + gap) % gap; d < total; d += gap) {
      s = d;
      for (i = 0; i < segs.length; i++) { if (s <= segs[i]) break; s -= segs[i]; }
      if (i >= segs.length) break;
      p = s / segs[i];
      ctx.beginPath(); ctx.arc(pts[i][0] + (pts[i + 1][0] - pts[i][0]) * p, pts[i][1] + (pts[i + 1][1] - pts[i][1]) * p, 3.2, 0, 7); ctx.fill();
    }
    ctx.restore();
  },
  fix: function (v, n) { var s = Math.abs(v).toFixed(n == null ? 2 : n); return (v < 0 && +s !== 0 ? '−' : '') + s; },
};

/**
 * Lab: drifting electrons. Each electron has a random thermal velocity plus a field-driven velocity that
 * grows steadily and is wiped out at every collision — so the average slide really is a·τ.
 */
Sim.register('drift-lab', function (stage) {
  'use strict';
  var N = 8.5e28, QE = 1.6e-19, TAU = 0.35, VT = 105;
  var I = 2, area = 1, thermal = true, follow = false, parts = [], trail = [], last = 0, k;
  stage.tip.classList.add('is-gone');
  for (k = 0; k < 64; k++) parts.push({ x: Math.random(), y: Math.random() * 2 - 1, a: Math.random() * 6.283, u: 0 });
  var outJ = stage.readout('Current density'), outV = stage.readout('Drift speed'), outT = stage.readout('Time to drift 1 m'), outN = stage.readout('Electrons per second');
  stage.slider({ label: 'Current', min: 0, max: 10, step: 0.5, value: I, format: function (v) { return v.toFixed(1) + ' A'; }, onInput: function (v) { I = v; } });
  stage.slider({ label: 'Cross-section', min: 0.5, max: 4, step: 0.25, value: area, format: function (v) { return v.toFixed(2) + ' mm²'; }, onInput: function (v) { area = v; } });
  stage.toggle({ label: 'Thermal motion', value: true, onChange: function (on) { thermal = on; } });
  stage.toggle({ label: 'Follow one electron', value: false, onChange: function (on) { follow = on; trail = []; } });
  stage.setAnimating(true);

  stage.draw(function (ctx, s) {
    var t = s.theme, vd = I / (N * QE * area * 1e-6), mm = vd * 1e3, vpx = Math.min(170, 46 * mm);
    var x0 = 26, x1 = s.w - 26, W = x1 - x0, cy = s.h / 2 + 4, hw = Math.min(s.h / 2 - 62, 26 + 22 * Math.sqrt(area)), i, p, dt, vx, vy, px, py;
    dt = last ? Math.min(0.05, Math.max(0, s.time - last)) : 0; last = s.time;
    if (!s.animating()) dt = 0;

    // the wire and its lattice of ions
    ctx.save();
    ctx.fillStyle = t.light ? 'rgba(190,120,40,.16)' : 'rgba(255,170,90,.10)'; ctx.strokeStyle = t.ink3; ctx.lineWidth = 1.5;
    ctx.beginPath(); if (ctx.roundRect) ctx.roundRect(x0, cy - hw, W, 2 * hw, 10); else ctx.rect(x0, cy - hw, W, 2 * hw); ctx.fill(); ctx.stroke();
    ctx.fillStyle = t.pos; ctx.globalAlpha = 0.28;
    for (px = x0 + 22; px < x1 - 8; px += 38) for (py = cy - hw + 16; py < cy + hw - 6; py += 30) { ctx.beginPath(); ctx.arc(px, py, 4.5, 0, 7); ctx.fill(); }
    ctx.restore();

    // electrons: thermal velocity + field-driven velocity that resets at each collision
    for (i = 0; i < parts.length; i++) {
      p = parts[i];
      if (dt) {
        if (Math.random() < dt / TAU) { p.a = Math.random() * 6.283; p.u = 0; }
        p.u += vpx / TAU * dt;
        vx = (thermal ? VT * Math.cos(p.a) : 0) - p.u; vy = thermal ? VT * Math.sin(p.a) : 0;
        p.x += vx * dt / W; p.y += vy * dt / hw;
        if (p.y > 0.92) { p.y = 0.92; p.a = -p.a; } else if (p.y < -0.92) { p.y = -0.92; p.a = -p.a; }
        if (p.x < 0) { p.x += 1; if (!i) trail.push(null); } else if (p.x >= 1) { p.x -= 1; if (!i) trail.push(null); }
        if (!i && follow) { trail.push([p.x, p.y]); if (trail.length > 420) trail.shift(); }
      }
    }
    if (follow && trail.length > 1) {
      ctx.save(); ctx.strokeStyle = t.warn; ctx.lineWidth = 1.6; ctx.globalAlpha = 0.85; ctx.lineJoin = 'round'; ctx.beginPath();
      var pen = false;
      trail.forEach(function (q) { if (!q) { pen = false; return; } var X = x0 + q[0] * W, Y = cy + q[1] * hw; if (pen) ctx.lineTo(X, Y); else ctx.moveTo(X, Y); pen = true; });
      ctx.stroke(); ctx.restore();
    }
    for (i = parts.length - 1; i >= 0; i--) {
      p = parts[i]; px = x0 + p.x * W; py = cy + p.y * hw;
      ctx.save(); ctx.fillStyle = follow && !i ? t.warn : t.neg; ctx.globalAlpha = follow && i ? 0.45 : 1;
      ctx.beginPath(); ctx.arc(px, py, follow && !i ? 6 : 4, 0, 7); ctx.fill(); ctx.restore();
    }

    // arrows
    var top = cy - hw - 22, bot = cy + hw + 24, mid = s.w / 2;
    Sim.arrow(ctx, mid - 70, top, mid + 70, top, { color: t.accent, width: 2.6, head: 10 });
    Sim.label(ctx, 'field E  ·  conventional current I', mid, top - 15, { size: 12, weight: 650, color: t.accent });
    if (I > 0) {
      Sim.arrow(ctx, mid + 70, bot, mid - 70, bot, { color: t.neg, width: 2.6, head: 10 });
      Sim.label(ctx, 'electron drift', mid, bot + 15, { size: 12, weight: 650, color: t.neg });
    } else Sim.label(ctx, 'no field: plenty of motion, no drift', mid, bot + 6, { size: 12, weight: 650, color: t.ink2 });

    var T = vd > 0 ? 1 / vd : Infinity;
    outJ((I / area).toFixed(2) + ' A/mm²', 'J = I / A');
    outV(mm < 0.1 ? (mm * 1000).toFixed(0) + ' µm/s' : mm.toFixed(2) + ' mm/s', 'v = I / (neA)');
    outT(!isFinite(T) ? 'never' : T > 5400 ? (T / 3600).toFixed(1) + ' hours' : (T / 60).toFixed(1) + ' minutes', mm > 0 && mm < 13 ? 'a snail manages ~13 mm/s' : '');
    outN(I > 0 ? (I / QE / 1e19).toFixed(2) + ' × 10¹⁹' : '0', 'past any cross-section');
  });
}, { unitsWide: 10, aspect: 0.42, minHeight: 280, maxHeight: 340, hint: '' });

/**
 * Lab: one cell, one load. Power delivered against load resistance, with an energy-budget bar.
 */
Sim.register('cell-lab', function (stage) {
  'use strict';
  var eps = 6, r = 2, R = 2, RMAX = 12, twin = false, showEff = false;
  var H = stage.handle({ radius: 15, name: 'load' });
  var outI = stage.readout('Current'), outV = stage.readout('Terminal voltage'), outP = stage.readout('Power to load'), outL = stage.readout('Lost inside cell'), outE = stage.readout('Efficiency');
  stage.slider({ label: 'emf ε', min: 1, max: 12, step: 0.5, value: eps, format: function (v) { return v.toFixed(1) + ' V'; }, onInput: function (v) { eps = v; } });
  stage.slider({ label: 'internal r', min: 0.5, max: 5, step: 0.5, value: r, format: function (v) { return v.toFixed(1) + ' Ω'; }, onInput: function (v) { r = v; } });
  var sR = stage.slider({ label: 'load R', min: 0, max: RMAX, step: 0.1, value: R, format: function (v) { return v.toFixed(1) + ' Ω'; }, onInput: function (v) { R = v; } });
  stage.toggle({ label: 'Twin load', value: false, onChange: function (on) { twin = on; } });
  stage.toggle({ label: 'Efficiency curve', value: false, onChange: function (on) { showEff = on; } });
  function box() { return { l: 48, r: stage.w - 16, t: 58, b: stage.h - 34 }; }
  function P(x) { return eps * eps * x / ((x + r) * (x + r)); }
  H.onDrag = function () { var b = box(), p = stage.toScreen(H.x, H.y); R = Math.round(Sim.clamp((p[0] - b.l) / (b.r - b.l) * RMAX, 0, RMAX) * 10) / 10; sR.set(R); };

  stage.draw(function (ctx, s) {
    var t = s.theme, b = box(), Pm = eps * eps / (4 * r), top = Pm * 1.18, x, i;
    var X = function (v) { return b.l + v / RMAX * (b.r - b.l); }, Y = function (p) { return b.b - p / top * (b.b - b.t); };
    var cur = eps / (R + r), V = cur * R, PL = cur * cur * R, Pin = cur * cur * r, eff = R / (R + r);

    // energy budget bar
    var bw = b.r - b.l, split = b.l + bw * eff;
    ctx.save(); ctx.globalAlpha = 0.85;
    ctx.fillStyle = t.ok; ctx.fillRect(b.l, 14, Math.max(0, split - b.l), 18); ctx.fillStyle = t.pos; ctx.fillRect(split, 14, b.r - split, 18); ctx.restore();
    Sim.label(ctx, 'to the load ' + Math.round(eff * 100) + '%', b.l, 43, { size: 11, weight: 650, color: t.ok, align: 'left' });
    Sim.label(ctx, 'lost in the cell ' + Math.round((1 - eff) * 100) + '%', b.r, 43, { size: 11, weight: 650, color: t.pos, align: 'right' });

    // axes
    ctx.save(); ctx.strokeStyle = t.grid; ctx.lineWidth = 1; ctx.beginPath();
    for (i = 2; i <= RMAX; i += 2) { ctx.moveTo(Math.round(X(i)) + 0.5, b.t); ctx.lineTo(Math.round(X(i)) + 0.5, b.b); }
    ctx.stroke(); ctx.strokeStyle = t.ink3; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(b.l, b.t); ctx.lineTo(b.l, b.b); ctx.lineTo(b.r, b.b); ctx.stroke(); ctx.restore();
    for (i = 0; i <= RMAX; i += 2) Sim.label(ctx, String(i), X(i), b.b + 12, { size: 11, weight: 560, color: t.ink3 });
    Sim.label(ctx, 'load R (Ω)', b.r, b.b + 26, { size: 11, weight: 650, color: t.ink2, align: 'right' });
    Sim.label(ctx, 'power in load (W)', b.l + 8, b.t + 2, { size: 11, weight: 650, color: t.ink2, align: 'left' });

    // peak guides
    ctx.save(); ctx.setLineDash([4, 5]); ctx.strokeStyle = t.ink3; ctx.lineWidth = 1.2; ctx.beginPath();
    ctx.moveTo(X(r), Y(Pm)); ctx.lineTo(X(r), b.b); ctx.moveTo(b.l, Y(Pm)); ctx.lineTo(X(r), Y(Pm)); ctx.stroke(); ctx.restore();
    Sim.label(ctx, 'R = r', X(r), Y(Pm) - 14, { size: 11, weight: 700, color: t.ink2, plate: t.plate });
    Sim.label(ctx, Pm.toFixed(2), b.l - 6, Y(Pm), { size: 11, weight: 600, color: t.ink3, align: 'right' });

    if (showEff) {
      ctx.save(); ctx.strokeStyle = t.violet; ctx.lineWidth = 1.8; ctx.setLineDash([2, 5]); ctx.beginPath();
      for (x = 0; x <= RMAX; x += 0.1) { var ye = b.b - x / (x + r) * (b.b - b.t); x ? ctx.lineTo(X(x), ye) : ctx.moveTo(X(x), ye); }
      ctx.stroke(); ctx.restore();
      Sim.label(ctx, 'efficiency → 100%', b.r - 4, b.b - RMAX / (RMAX + r) * (b.b - b.t) - 12, { size: 11, weight: 650, color: t.violet, align: 'right' });
    }
    // power curve
    ctx.save(); ctx.strokeStyle = t.accent; ctx.lineWidth = 2.6; ctx.lineJoin = 'round'; ctx.beginPath();
    for (x = 0; x <= RMAX + 0.001; x += 0.05) x ? ctx.lineTo(X(x), Y(P(x))) : ctx.moveTo(X(x), Y(P(x)));
    ctx.stroke(); ctx.restore();

    if (twin && R > 0.05) {
      var R2 = r * r / R;
      if (R2 <= RMAX && Math.abs(R2 - R) > 0.15) {
        ctx.save(); ctx.setLineDash([3, 4]); ctx.strokeStyle = t.warn; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(X(R), Y(PL)); ctx.lineTo(X(R2), Y(PL)); ctx.stroke();
        ctx.setLineDash([]); ctx.fillStyle = t.warn; ctx.beginPath(); ctx.arc(X(R2), Y(PL), 6, 0, 7); ctx.fill(); ctx.restore();
        Sim.label(ctx, 'twin: ' + R2.toFixed(2) + ' Ω', X(R2), Y(PL) + 20, { size: 11, weight: 700, color: t.warn, plate: t.plate });
      }
      Sim.label(ctx, 'R × twin = ' + (R * (r * r / R)).toFixed(2) + ' = r²', b.r - 4, b.t + 18, { size: 11, weight: 700, color: t.warn, align: 'right' });
    }
    // the handle
    var hx = X(R), hy = Y(PL), w = s.toWorld(hx, hy); H.x = w[0]; H.y = w[1];
    ctx.save(); ctx.fillStyle = t.accent; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(hx, hy, 10, 0, 7); ctx.fill(); ctx.stroke();
    if (H.active || s.focused(H)) { ctx.strokeStyle = t.accent; ctx.globalAlpha = 0.5; ctx.beginPath(); ctx.arc(hx, hy, 18, 0, 7); ctx.stroke(); }
    ctx.restore();

    outI(cur.toFixed(2) + ' A', R < 0.05 ? 'short circuit: ε / r' : 'ε / (R + r)');
    outV(V.toFixed(2) + ' V', 'ε − Ir');
    outP(PL.toFixed(2) + ' W', Math.abs(R - r) < 0.06 ? 'the maximum: ε² / 4r' : R < r ? 'load too small' : 'load too large');
    outL(Pin.toFixed(2) + ' W', 'I²r, heats the cell');
    outE(Math.round(eff * 100) + '%', 'R / (R + r)');
  });
}, { unitsWide: 10, aspect: 0.58, minHeight: 320, maxHeight: 480, hint: 'Drag the dot along the curve' });

/**
 * Lab: two batteries sharing a load — node-voltage solution, with marching dots for the three currents.
 */
Sim.register('kirchhoff-lab', function (stage) {
  'use strict';
  var v = { e1: 10, e2: 6, R1: 2, R2: 2, R3: 1 }, ph = [0, 0, 0], last = 0, S = {};
  stage.tip.classList.add('is-gone');
  var o1 = stage.readout('I₁ (left branch)'), o2 = stage.readout('I₂ (right branch)'), o3 = stage.readout('I₃ (load)'), oV = stage.readout('Voltage at junction A');
  function sl(key, label, min, max, unit) { S[key] = stage.slider({ label: label, min: min, max: max, step: 0.5, value: v[key], format: function (x) { return x.toFixed(1) + ' ' + unit; }, onInput: function (x) { v[key] = x; } }); }
  sl('e1', 'ε₁', 0, 12, 'V'); sl('e2', 'ε₂', 0, 12, 'V'); sl('R1', 'R₁', 1, 10, 'Ω'); sl('R2', 'R₂', 1, 10, 'Ω'); sl('R3', 'R₃ (load)', 1, 10, 'Ω');
  stage.button({ label: 'Reset', onClick: function () { v = { e1: 10, e2: 6, R1: 2, R2: 2, R3: 1 }; Object.keys(S).forEach(function (k) { S[k].set(v[k]); }); } });
  stage.setAnimating(true);

  stage.draw(function (ctx, s) {
    var t = s.theme, xl = Math.max(46, s.w * 0.14), xm = s.w * 0.5, xr = s.w - xl, yt = 62, yb = s.h - 34, hgt = yb - yt;
    var VA = (v.e1 / v.R1 + v.e2 / v.R2) / (1 / v.R1 + 1 / v.R2 + 1 / v.R3), I1 = (v.e1 - VA) / v.R1, I2 = (v.e2 - VA) / v.R2, I3 = VA / v.R3;
    var dt = last ? Math.min(0.05, Math.max(0, s.time - last)) : 0; last = s.time; if (!s.animating()) dt = 0;
    [I1, I2, I3].forEach(function (c, i) { ph[i] += Sim.clamp(c * 16, -170, 170) * dt; });
    var yc = yb - hgt * 0.26, yr1 = yt + hgt * 0.1, yr2 = yt + hgt * 0.52;

    CE.wire(ctx, [[xl, yt], [xr, yt]], t.ink2); CE.wire(ctx, [[xl, yb], [xr, yb]], t.ink2);
    CE.flow(ctx, [[xm, yb], [xl, yb], [xl, yt], [xm, yt]], ph[0], t.accent);
    CE.flow(ctx, [[xm, yb], [xr, yb], [xr, yt], [xm, yt]], ph[1], I2 < 0 ? t.pos : t.accent);
    CE.flow(ctx, [[xm, yt], [xm, yb]], ph[2], t.ok);
    [[xl, v.e1, v.R1, '₁'], [xr, v.e2, v.R2, '₂']].forEach(function (q, i) {
      var x = q[0], side = i ? 1 : -1, al = i ? 'left' : 'right';
      if (s.w < 560) { side = -side; al = i ? 'right' : 'left'; } // phones: labels go inside the loop
      CE.wire(ctx, [[x, yb], [x, yc + 22]], t.ink2); CE.cell(ctx, x, yc + 22, x, yc - 22, t.ink); CE.wire(ctx, [[x, yc - 22], [x, yr2]], t.ink2);
      CE.zig(ctx, x, yr2, x, yr1, t.ink); CE.wire(ctx, [[x, yr1], [x, yt]], t.ink2);
      Sim.label(ctx, 'ε' + q[3] + ' = ' + q[1].toFixed(1) + ' V', x + side * 22, yc, { size: 12, weight: 650, color: t.ink, align: al, plate: t.plate });
      Sim.label(ctx, 'R' + q[3] + ' = ' + q[2].toFixed(1) + ' Ω', x + side * 16, (yr1 + yr2) / 2, { size: 12, weight: 650, color: t.ink, align: al, plate: t.plate });
      Sim.label(ctx, '+', x - side * 22, yc - 13, { size: 13, weight: 700, color: t.ink3 });
    });
    CE.wire(ctx, [[xm, yt], [xm, yt + hgt * 0.3]], t.ink2); CE.zig(ctx, xm, yt + hgt * 0.3, xm, yt + hgt * 0.7, t.ink); CE.wire(ctx, [[xm, yt + hgt * 0.7], [xm, yb]], t.ink2);
    Sim.label(ctx, 'R₃ = ' + v.R3.toFixed(1) + ' Ω', xm + 16, yt + hgt * 0.5, { size: 12, weight: 650, color: t.ink, align: 'left', plate: t.plate });
    ctx.save(); ctx.fillStyle = t.ink; [[xm, yt], [xm, yb]].forEach(function (p) { ctx.beginPath(); ctx.arc(p[0], p[1], 4, 0, 7); ctx.fill(); }); ctx.restore();
    Sim.label(ctx, 'A', xm, yt - 14, { size: 13, weight: 750, color: t.ink }); Sim.label(ctx, 'B (0 V)', xm, yb + 15, { size: 12, weight: 700, color: t.ink2 });
    Sim.label(ctx, 'I₁ + I₂ = I₃ :  ' + CE.fix(I1) + ' + ' + CE.fix(I2) + ' = ' + CE.fix(I3) + ' A', s.w / 2, 22, { size: 13, weight: 700, color: t.accent, plate: t.plate });

    var dir = function (c, up) { return Math.abs(c) < 0.005 ? 'no current' : (c > 0) === up ? 'upward, towards A' : 'downward, away from A'; };
    o1(CE.fix(I1) + ' A', dir(I1, true)); o2(CE.fix(I2) + ' A', I2 < -0.005 ? 'battery 2 is being charged' : dir(I2, true));
    o3(CE.fix(I3) + ' A', 'through the load'); oV(CE.fix(VA) + ' V', VA > v.e2 + 0.005 ? 'above ε₂: charging battery 2' : 'the same across all three branches');
  });
}, { unitsWide: 10, aspect: 0.56, minHeight: 320, maxHeight: 460, hint: '' });

/**
 * Lab: two rated bulbs on 220 V, in series or in parallel. Glow follows the power actually dissipated.
 */
Sim.register('bulb-lab', function (stage) {
  'use strict';
  var V = 220, P = [25, 100], series = false;
  stage.tip.classList.add('is-gone');
  var o1 = stage.readout('Bulb 1 actually uses'), o2 = stage.readout('Bulb 2 actually uses'), oT = stage.readout('Total power'), oI = stage.readout('Current from supply');
  var fmt = function (x) { return x + ' W'; };
  stage.slider({ label: 'Bulb 1 label', min: 15, max: 200, step: 5, value: P[0], format: fmt, onInput: function (x) { P[0] = x; } });
  stage.slider({ label: 'Bulb 2 label', min: 15, max: 200, step: 5, value: P[1], format: fmt, onInput: function (x) { P[1] = x; } });
  var bP = stage.toggle({ label: 'Parallel', value: true, onChange: function () { series = false; sync(); } });
  var bS = stage.toggle({ label: 'Series', value: false, onChange: function () { series = true; sync(); } });
  function sync() { bP.setAttribute('aria-pressed', String(!series)); bS.setAttribute('aria-pressed', String(series)); }
  function lamp(ctx, t, x, y, p, name, rated, volts) {
    var k = Math.pow(Sim.clamp(p / 120, 0, 1), 0.55), R = 26, g;
    ctx.save();
    if (k > 0.01) { g = ctx.createRadialGradient(x, y, 4, x, y, R + 70 * k + 10); g.addColorStop(0, 'rgba(255,214,110,' + (0.25 + 0.7 * k) + ')'); g.addColorStop(1, 'rgba(255,214,110,0)'); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, R + 70 * k + 10, 0, 7); ctx.fill(); }
    ctx.fillStyle = 'rgba(255,226,150,' + (0.08 + 0.85 * k) + ')'; ctx.strokeStyle = t.ink; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(x, y, R, 0, 7); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = k > 0.5 ? '#7a4a00' : t.ink2; ctx.lineWidth = 1.8; ctx.beginPath(); ctx.moveTo(x - 12, y + 6);
    for (var i = 0; i < 6; i++) ctx.lineTo(x - 12 + 4 * (i + 0.5), y + (i % 2 ? 6 : -6)); ctx.lineTo(x + 12, y + 6); ctx.stroke(); ctx.restore();
    Sim.label(ctx, (stage.w < 560 ? '' : name + ' · ') + 'label ' + rated + ' W', x, y + R + 18, { size: 12, weight: 650, color: t.ink2, plate: t.plate });
    Sim.label(ctx, p.toFixed(1) + ' W' + (stage.w < 560 ? '' : '  at ' + volts.toFixed(0) + ' V'), x, y + R + 40, { size: 13, weight: 750, color: t.accent, plate: t.plate });
  }
  stage.draw(function (ctx, s) {
    var t = s.theme, R1 = V * V / P[0], R2 = V * V / P[1], p1, p2, v1, v2, I;
    if (series) { I = V / (R1 + R2); p1 = I * I * R1; p2 = I * I * R2; v1 = I * R1; v2 = I * R2; } else { p1 = P[0]; p2 = P[1]; v1 = v2 = V; I = V / R1 + V / R2; }
    var xs = Math.max(34, s.w * 0.08), x1 = s.w * 0.36, x2 = s.w * 0.72, xe = s.w - 26, yt = 46, yb = s.h - 30, ym = yt + (yb - yt) * 0.36;
    if (series) {
      CE.wire(ctx, [[xs, yb], [xs, ym], [x1 - 26, ym]], t.ink2); CE.wire(ctx, [[x1 + 26, ym], [x2 - 26, ym]], t.ink2); CE.wire(ctx, [[x2 + 26, ym], [xe, ym], [xe, yb], [xs, yb]], t.ink2);
    } else {
      CE.wire(ctx, [[xs, yb], [xs, yt], [x2, yt]], t.ink2); CE.wire(ctx, [[xs, yb], [x2, yb]], t.ink2);
      [x1, x2].forEach(function (x) { CE.wire(ctx, [[x, yt], [x, ym - 26]], t.ink2); CE.wire(ctx, [[x, ym + 26], [x, yb]], t.ink2); });
    }
    Sim.label(ctx, '220 V supply', xs + 4, yb - 14, { size: 11, weight: 700, color: t.ink2, align: 'left', plate: t.plate });
    lamp(ctx, t, x1, ym, p1, 'Bulb 1', P[0], v1); lamp(ctx, t, x2, ym, p2, 'Bulb 2', P[1], v2);
    Sim.label(ctx, series ? 'Series: same current through both' : 'Parallel: same voltage across both', s.w / 2, 18, { size: 12, weight: 700, color: t.ink2 });
    o1(p1.toFixed(1) + ' W', 'R₁ = ' + Math.round(R1) + ' Ω'); o2(p2.toFixed(1) + ' W', 'R₂ = ' + Math.round(R2) + ' Ω');
    oT((p1 + p2).toFixed(1) + ' W', series ? 'P₁P₂/(P₁+P₂) of the labels' : 'P₁ + P₂ of the labels'); oI(I.toFixed(3) + ' A', p1 > p2 + 0.05 ? 'bulb 1 is brighter' : p2 > p1 + 0.05 ? 'bulb 2 is brighter' : 'equally bright');
  });
}, { unitsWide: 10, aspect: 0.52, minHeight: 300, maxHeight: 420, hint: '' });

/**
 * Lab: metre bridge with a mystery resistor. The galvanometer current comes from solving the
 * unbalanced bridge exactly (wire 10 Ω, galvanometer 40 Ω), so the needle behaves like the real thing.
 */
Sim.register('bridge-lab', function (stage) {
  'use strict';
  var POOL = [3, 4, 6, 7.5, 8, 12, 15, 18, 20, 24], X = 12, Rk = 10, eps = 2, l = 20, reveal = false, RW = 10, G = 40;
  var J = stage.handle({ radius: 14, name: 'jockey' });
  var oL = stage.readout('Jockey at'), oG = stage.readout('Galvanometer'), oC = stage.readout('R · l / (100 − l)'), oX = stage.readout('Mystery X');
  stage.slider({ label: 'Known R', min: 1, max: 20, step: 0.5, value: Rk, format: function (x) { return x.toFixed(1) + ' Ω'; }, onInput: function (x) { Rk = x; } });
  stage.slider({ label: 'Battery emf', min: 1, max: 6, step: 0.5, value: eps, format: function (x) { return x.toFixed(1) + ' V'; }, onInput: function (x) { eps = x; } });
  var bR = stage.toggle({ label: 'Reveal X', value: false, onChange: function (on) { reveal = on; } });
  stage.button({ label: 'New mystery X', onClick: function () { var n; do { n = POOL[Math.floor(Math.random() * POOL.length)]; } while (n === X); X = n; reveal = false; bR.setAttribute('aria-pressed', 'false'); l = 20; if (window.FX) FX.play('select'); } });
  function geo() { return { xa: 40, xb: stage.w - 40, yw: stage.h - 76, ys: 46 }; }
  J.onDrag = function () { var g = geo(), p = stage.toScreen(J.x, J.y); l = Math.round(Sim.clamp((p[0] - g.xa) / (g.xb - g.xa) * 100, 1, 99) * 10) / 10; };

  stage.draw(function (ctx, s) {
    var t = s.theme, g = geo(), L = g.xb - g.xa, xj = g.xa + L * l / 100, xc = s.w / 2, i, x;
    var w = s.toWorld(xj, g.yw); J.x = w[0]; J.y = w[1];
    // solve for the potentials of D (strip mid-point) and J (jockey); A at ε, B at 0
    var r1 = RW * l / 100, r2 = RW * (100 - l) / 100, a11 = 1 / X + 1 / Rk + 1 / G, a12 = -1 / G, a22 = 1 / r1 + 1 / r2 + 1 / G, b1 = eps / X, b2 = eps / r1;
    var det = a11 * a22 - a12 * a12, VD = (b1 * a22 - a12 * b2) / det, VJ = (a11 * b2 - a12 * b1) / det, Ig = (VD - VJ) / G;
    var l0 = 100 * X / (X + Rk), nul = Math.abs(l - l0) < 0.16;

    // wire + scale
    ctx.save(); ctx.strokeStyle = t.warn; ctx.lineWidth = 4; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(g.xa, g.yw); ctx.lineTo(g.xb, g.yw); ctx.stroke();
    ctx.strokeStyle = t.ink3; ctx.lineWidth = 1; ctx.beginPath();
    for (i = 0; i <= 100; i += 2) { x = Math.round(g.xa + L * i / 100) + 0.5; ctx.moveTo(x, g.yw + 7); ctx.lineTo(x, g.yw + (i % 10 ? 11 : 16)); }
    ctx.stroke(); ctx.restore();
    for (i = 0; i <= 100; i += (s.w < 480 ? 20 : 10)) Sim.label(ctx, String(i), g.xa + L * i / 100, g.yw + 27, { size: 10.5, weight: 560, color: t.ink3 });
    Sim.label(ctx, 'cm', g.xb + 16, g.yw + 27, { size: 10.5, weight: 560, color: t.ink3 });

    // strips, gaps, resistors
    var gx1 = g.xa + L * 0.06, gx2 = g.xa + L * 0.3, gx3 = g.xb - L * 0.3, gx4 = g.xb - L * 0.06;
    CE.wire(ctx, [[g.xa, g.yw], [g.xa, g.ys], [gx1, g.ys]], t.ink2, 3); CE.wire(ctx, [[gx2, g.ys], [gx3, g.ys]], t.ink2, 3); CE.wire(ctx, [[gx4, g.ys], [g.xb, g.ys], [g.xb, g.yw]], t.ink2, 3);
    CE.zig(ctx, gx1, g.ys, gx2, g.ys, t.accent, 2.4); CE.zig(ctx, gx3, g.ys, gx4, g.ys, t.ink, 2.4);
    Sim.label(ctx, reveal ? 'X = ' + X + ' Ω' : 'X = ?', (gx1 + gx2) / 2, g.ys - 20, { size: 13, weight: 750, color: t.accent });
    Sim.label(ctx, 'R = ' + Rk.toFixed(1) + ' Ω', (gx3 + gx4) / 2, g.ys - 20, { size: 13, weight: 700, color: t.ink });
    Sim.label(ctx, 'A', g.xa - 14, g.yw, { size: 13, weight: 750, color: t.ink2 }); Sim.label(ctx, 'B', g.xb + 14, g.yw, { size: 13, weight: 750, color: t.ink2 });

    // galvanometer dial
    var gy = (g.ys + g.yw) / 2 - 2, gr = Math.min(34, (g.yw - g.ys) / 2 - 22), ang = Math.tanh(Ig / 1e-3) * 1.05;
    CE.wire(ctx, [[xc, g.ys], [xc, gy - gr]], t.ink2); CE.wire(ctx, [[xc, gy + gr], [xc, gy + gr + 8], [xj, gy + gr + 8], [xj, g.yw - 12]], t.ink2);
    ctx.save(); ctx.fillStyle = t.plate; ctx.strokeStyle = nul ? t.ok : t.ink; ctx.lineWidth = nul ? 3 : 2; ctx.beginPath(); ctx.arc(xc, gy, gr, 0, 7); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = t.ink3; ctx.lineWidth = 1.2; ctx.beginPath();
    for (i = -3; i <= 3; i++) { var a = -Math.PI / 2 + i * 0.35; ctx.moveTo(xc + Math.cos(a) * (gr - 8), gy + Math.sin(a) * (gr - 8)); ctx.lineTo(xc + Math.cos(a) * (gr - 3), gy + Math.sin(a) * (gr - 3)); }
    ctx.stroke();
    ctx.strokeStyle = nul ? t.ok : t.pos; ctx.lineWidth = 2.6; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(xc, gy + gr * 0.45);
    ctx.lineTo(xc + Math.sin(ang) * (gr - 9), gy + gr * 0.45 - Math.cos(ang) * (gr * 1.25 - 9)); ctx.stroke(); ctx.restore();
    Sim.label(ctx, 'D', xc + 12, g.ys - 12, { size: 12, weight: 700, color: t.ink2 });
    Sim.label(ctx, nul ? 'balanced' : 'G', xc, gy + gr * 0.72, { size: 10.5, weight: 700, color: nul ? t.ok : t.ink3 });

    // jockey
    ctx.save(); ctx.fillStyle = nul ? t.ok : t.accent; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(xj, g.yw - 2); ctx.lineTo(xj - 9, g.yw - 20); ctx.lineTo(xj + 9, g.yw - 20); ctx.closePath(); ctx.fill(); ctx.stroke();
    if (J.active || s.focused(J)) { ctx.strokeStyle = t.accent; ctx.globalAlpha = 0.5; ctx.beginPath(); ctx.arc(xj, g.yw - 10, 20, 0, 7); ctx.stroke(); }
    ctx.restore();
    Sim.label(ctx, 'l = ' + l.toFixed(1) + ' cm', xj + (l > 80 ? -54 : 54), g.yw - 30, { size: 12, weight: 750, color: nul ? t.ok : t.accent, plate: t.plate });

    var mA = Ig * 1e3;
    oL(l.toFixed(1) + ' cm', 'from end A');
    oG(nul ? 'zero' : Math.abs(mA) < 1 ? CE.fix(mA * 1000, 0) + ' µA' : CE.fix(mA, 2) + ' mA', nul ? 'null point found' : mA < 0 ? 'move the jockey right →' : '← move the jockey left');
    oC((Rk * l / (100 - l)).toFixed(2) + ' Ω', nul ? 'this is X' : 'equals X only at the null');
    oX(reveal ? X + ' Ω' : '?', reveal ? 'null at ' + l0.toFixed(1) + ' cm' : 'find the null first');
  });
}, { unitsWide: 10, aspect: 0.5, minHeight: 320, maxHeight: 420, hint: 'Drag the jockey' });
/* lab:current-electricity:end */
